"""Niyam rulebook engine.

Rules live in YAML so that people and agents can read and review them:

- ``schema/person.yaml``       the facts about a person that rules may use
- ``parameters/<state>/<scheme>/<name>.yaml``  dated values (OpenFisca format)
- ``schemes/<state>/<scheme>.yaml``  conditions and benefit, each with a source
- ``tests/<state>/<scheme>.yaml``    test citizens with expected results

Every parameter value and every condition is dated, so the rulebook can answer
"what were the rules on a given day?" and history is never overwritten.
"""

from __future__ import annotations

import datetime as dt
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import yaml

from .safe_eval import RuleExpressionError, evaluate, names_used

ROOT = Path(__file__).resolve().parent.parent


def _to_date(value: Any) -> dt.date:
    if isinstance(value, dt.datetime):
        return value.date()
    if isinstance(value, dt.date):
        return value
    return dt.date.fromisoformat(str(value))


@dataclass
class ParamValue:
    start: dt.date
    value: Any
    reference: dict[str, Any]


@dataclass
class Parameter:
    key: str
    description: str
    unit: str | None
    values: list[ParamValue]

    def at(self, on: dt.date) -> ParamValue | None:
        current = None
        for v in self.values:
            if v.start <= on:
                current = v
        return current


@dataclass
class Condition:
    id: str
    text: str
    when: str
    source: dict[str, Any]
    valid_from: dt.date
    valid_until: dt.date | None = None
    kind: str = "eligibility"

    def active(self, on: dt.date) -> bool:
        return self.valid_from <= on and (self.valid_until is None or on <= self.valid_until)


@dataclass
class Scheme:
    id: str
    data: dict[str, Any]
    conditions: list[Condition]
    params: dict[str, Parameter] = field(default_factory=dict)

    @property
    def name(self) -> str:
        return self.data["name"]

    def params_at(self, on: dt.date) -> dict[str, Any]:
        out = {}
        for name, p in self.params.items():
            v = p.at(on)
            if v is not None:
                out[name] = v.value
        return out


class Rulebook:
    def __init__(self, root: Path | str = ROOT):
        self.root = Path(root)
        self.person_schema: dict[str, dict[str, Any]] = {}
        self.schemes: dict[str, Scheme] = {}
        self.sources: dict[str, dict[str, Any]] = {}
        self._load()

    # ------------------------------------------------------------------ load
    def _load(self) -> None:
        schema = yaml.safe_load((self.root / "schema" / "person.yaml").read_text(encoding="utf-8"))
        self.person_schema = schema["fields"]
        src_file = self.root / "sources" / "index.yaml"
        if src_file.exists():
            self.sources = yaml.safe_load(src_file.read_text(encoding="utf-8")) or {}
        for path in sorted((self.root / "schemes").rglob("*.yaml")):
            data = yaml.safe_load(path.read_text(encoding="utf-8"))
            conditions = [
                Condition(
                    id=c["id"],
                    text=c["text"],
                    when=c["when"],
                    source=c.get("source", {}),
                    valid_from=_to_date(c["valid_from"]),
                    valid_until=_to_date(c["valid_until"]) if c.get("valid_until") else None,
                    kind=c.get("kind", "eligibility"),
                )
                for c in data.get("conditions", [])
            ]
            scheme = Scheme(id=data["id"], data=data, conditions=conditions)
            param_dir = self.root / "parameters" / Path(*data["id"].split("."))
            for ppath in sorted(param_dir.glob("*.yaml")):
                pdata = yaml.safe_load(ppath.read_text(encoding="utf-8"))
                values = []
                for start, entry in (pdata.get("values") or {}).items():
                    entry = entry if isinstance(entry, dict) else {"value": entry}
                    values.append(
                        ParamValue(
                            start=_to_date(start),
                            value=entry.get("value"),
                            reference=(entry.get("metadata") or {}).get("reference", {}),
                        )
                    )
                values.sort(key=lambda v: v.start)
                meta = pdata.get("metadata") or {}
                scheme.params[ppath.stem] = Parameter(
                    key=f"{data['id']}.{ppath.stem}",
                    description=pdata.get("description", ""),
                    unit=meta.get("unit"),
                    values=values,
                )
            self.schemes[scheme.id] = scheme

    # -------------------------------------------------------------- persons
    def normalise_person(self, person: dict[str, Any]) -> dict[str, Any]:
        out = {}
        for name, spec in self.person_schema.items():
            value = person.get(name, spec.get("default"))
            if value is None:
                out[name] = None
                continue
            kind = spec.get("type")
            if kind == "int":
                value = int(value)
            elif kind == "number":
                value = float(value)
            elif kind == "bool":
                value = value if isinstance(value, bool) else str(value).lower() in {"1", "true", "yes"}
            elif kind == "enum" and value not in spec.get("values", []):
                raise ValueError(f"{name} must be one of {spec.get('values')}, got {value!r}")
            out[name] = value
        unknown = set(person) - set(self.person_schema)
        if unknown:
            raise ValueError(f"unknown person fields: {sorted(unknown)}")
        return out

    # ------------------------------------------------------------- evaluate
    def evaluate(self, person: dict[str, Any], on: dt.date | str | None = None,
                 schemes: list[str] | None = None) -> dict[str, Any]:
        on = _to_date(on) if on else dt.date.today()
        p = self.normalise_person(person)
        results = {}
        for sid, scheme in self.schemes.items():
            if schemes and sid not in schemes:
                continue
            launched = _to_date(scheme.data["launched"])
            closed = scheme.data.get("closed")
            if on < launched or (closed and on > _to_date(closed)):
                results[sid] = {"eligible": False, "in_force": False, "monthly_inr": 0, "reasons": []}
                continue
            params = scheme.params_at(on)
            reasons = []
            for c in scheme.conditions:
                if not c.active(on):
                    continue
                met = bool(evaluate(c.when, p, params))
                reasons.append({
                    "id": c.id,
                    "text": self.render_text(c.text, params),
                    "met": met,
                    "source": c.source,
                })
            eligible = all(r["met"] for r in reasons)
            monthly = 0
            benefit = scheme.data.get("benefit", {}).get("monthly_inr")
            if eligible and benefit:
                monthly = evaluate(benefit, p, params)
                if isinstance(monthly, float) and monthly.is_integer():
                    monthly = int(monthly)
            results[sid] = {"eligible": eligible, "in_force": True, "monthly_inr": monthly, "reasons": reasons}
        return results

    @staticmethod
    def render_text(text: str, params: dict[str, Any]) -> str:
        def fmt(v: Any) -> str:
            if isinstance(v, list):
                return ", ".join(str(x) for x in v)
            if isinstance(v, (int, float)) and not isinstance(v, bool) and v >= 1000:
                return f"{v:,.0f}"
            return str(v)
        try:
            return text.format(**{k: fmt(v) for k, v in params.items()})
        except (KeyError, IndexError):
            return text

    # ----------------------------------------------------------- inspection
    def rules_at(self, scheme_id: str, on: dt.date | str | None = None) -> dict[str, Any]:
        on = _to_date(on) if on else dt.date.today()
        s = self.schemes[scheme_id]
        params = s.params_at(on)
        return {
            "id": s.id,
            "name": s.name,
            "as_of": on.isoformat(),
            "conditions": [
                {"id": c.id, "text": self.render_text(c.text, params), "when": c.when,
                 "source": c.source, "valid_from": c.valid_from.isoformat(),
                 "valid_until": c.valid_until.isoformat() if c.valid_until else None}
                for c in s.conditions if c.active(on)
            ],
            "parameters": {
                name: {"value": v.value, "since": v.start.isoformat(), "reference": v.reference,
                       "description": s.params[name].description, "unit": s.params[name].unit}
                for name in s.params if (v := s.params[name].at(on))
            },
        }

    def check(self) -> list[str]:
        """Structural validation. Returns a list of problems (empty means valid)."""
        problems = []
        for sid, s in self.schemes.items():
            for key in ("name", "launched", "department", "summary"):
                if key not in s.data:
                    problems.append(f"{sid}: missing '{key}'")
            ids = [c.id for c in s.conditions]
            for c in s.conditions:
                where = f"{sid}.{c.id}"
                for need in ("doc", "page", "quote"):
                    if not c.source.get(need):
                        problems.append(f"{where}: source is missing '{need}'")
                if c.source.get("doc") and c.source["doc"] not in self.sources:
                    problems.append(f"{where}: source doc '{c.source['doc']}' is not in sources/index.yaml")
                if c.valid_until and c.valid_until < c.valid_from:
                    problems.append(f"{where}: valid_until is before valid_from")
                try:
                    for root, attr in names_used(c.when):
                        if root == "person" and attr not in self.person_schema:
                            problems.append(f"{where}: unknown person field '{attr}'")
                        if root == "params" and attr not in s.params:
                            problems.append(f"{where}: unknown parameter '{attr}'")
                except RuleExpressionError as e:
                    problems.append(f"{where}: {e}")
            for cid in set(ids):
                periods = sorted((c.valid_from, c.valid_until or dt.date.max) for c in s.conditions if c.id == cid)
                for (a0, a1), (b0, _) in zip(periods, periods[1:]):
                    if b0 <= a1:
                        problems.append(f"{sid}.{cid}: overlapping validity periods")
            for name, p in s.params.items():
                if not p.values:
                    problems.append(f"{sid}: parameter '{name}' has no values")
                for v in p.values:
                    ref = v.reference or {}
                    if not ref.get("doc"):
                        problems.append(f"{sid}: parameter '{name}' value from {v.start} has no reference doc")
        return problems

"""Command line: python -m niyam_rulebook <check|test|simulate|rules|snapshot>."""

from __future__ import annotations

import argparse
import datetime as dt
import json
import sys
from pathlib import Path
from typing import Any

import yaml

from .engine import ROOT, Rulebook


def run_tests(rb: Rulebook, only: str | None = None) -> dict[str, Any]:
    results = {"passed": 0, "failed": 0, "failures": []}
    for path in sorted((rb.root / "tests").rglob("*.yaml")):
        suite = yaml.safe_load(path.read_text(encoding="utf-8"))
        sid = suite["scheme"]
        if only and sid != only:
            continue
        for case in suite.get("cases", []):
            try:
                out = rb.evaluate(case["person"], case["date"], schemes=[sid])[sid]
                problems = []
                for key, want in case["expect"].items():
                    if out.get(key) != want:
                        problems.append(f"{key}: expected {want!r}, got {out.get(key)!r}")
            except Exception as e:  # a broken rule file must fail the test, not crash the run
                problems, out = [f"error: {e}"], {}
            if problems:
                results["failed"] += 1
                unmet = [r["id"] for r in out.get("reasons", []) if not r["met"]]
                results["failures"].append({"file": str(path.relative_to(rb.root)), "case": case["name"],
                                            "problems": problems, "unmet_conditions": unmet,
                                            "source": case.get("source")})
            else:
                results["passed"] += 1
    return results


def snapshot(rb: Rulebook) -> dict[str, Any]:
    """Everything the website and API need, including full history."""
    out = {"generated_at": dt.datetime.now(dt.timezone.utc).isoformat(), "sources": rb.sources,
           "person_schema": rb.person_schema, "schemes": {}}
    for sid, s in rb.schemes.items():
        out["schemes"][sid] = {
            **{k: v for k, v in s.data.items() if k != "conditions"},
            "launched": str(s.data["launched"]),
            "conditions": [
                {"id": c.id, "text": c.text, "when": c.when, "kind": c.kind, "source": c.source,
                 "valid_from": c.valid_from.isoformat(),
                 "valid_until": c.valid_until.isoformat() if c.valid_until else None}
                for c in s.conditions
            ],
            "parameters": {
                name: {"description": p.description, "unit": p.unit,
                       "values": [{"start": v.start.isoformat(), "value": v.value, "reference": v.reference}
                                  for v in p.values]}
                for name, p in s.params.items()
            },
        }
    return out


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(prog="niyam_rulebook")
    ap.add_argument("--root", default=str(ROOT))
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("check", help="validate rule files")
    t = sub.add_parser("test", help="run test citizens")
    t.add_argument("--scheme")
    t.add_argument("--json", action="store_true")
    s = sub.add_parser("simulate", help="evaluate one person")
    s.add_argument("person", help="JSON object, or @file.json")
    s.add_argument("--date")
    sb = sub.add_parser("simulate-batch", help="evaluate many cases from a JSON list file")
    sb.add_argument("file", help="JSON list of {person, date, scheme}")
    r = sub.add_parser("rules", help="show the rules of a scheme on a date")
    r.add_argument("scheme")
    r.add_argument("--date")
    sn = sub.add_parser("snapshot", help="write the full rulebook as JSON")
    sn.add_argument("--out")
    args = ap.parse_args(argv)

    rb = Rulebook(Path(args.root))
    if args.cmd == "check":
        problems = rb.check()
        for p in problems:
            print(f"PROBLEM {p}")
        print("check: ok" if not problems else f"check: {len(problems)} problem(s)")
        return 1 if problems else 0
    if args.cmd == "test":
        problems = rb.check()
        res = run_tests(rb, args.scheme)
        res["check_problems"] = problems
        if args.json:
            print(json.dumps(res, ensure_ascii=False, indent=2))
        else:
            for p in problems:
                print(f"PROBLEM {p}")
            for f in res["failures"]:
                print(f"FAIL {f['file']} :: {f['case']}")
                for p in f["problems"]:
                    print(f"     {p}")
                if f["unmet_conditions"]:
                    print(f"     unmet conditions: {', '.join(f['unmet_conditions'])}")
            print(f"tests: {res['passed']} passed, {res['failed']} failed")
        return 1 if (res["failed"] or problems) else 0
    if args.cmd == "simulate":
        raw = Path(args.person[1:]).read_text(encoding="utf-8") if args.person.startswith("@") else args.person
        print(json.dumps(rb.evaluate(json.loads(raw), args.date), ensure_ascii=False, indent=2))
        return 0
    if args.cmd == "simulate-batch":
        out = []
        for case in json.loads(Path(args.file).read_text(encoding="utf-8")):
            try:
                res = rb.evaluate(case["person"], case.get("date"), schemes=[case["scheme"]] if case.get("scheme") else None)
                out.append({"ok": True, "result": res})
            except Exception as e:  # report bad cases instead of failing the batch
                out.append({"ok": False, "error": str(e)})
        print(json.dumps(out, ensure_ascii=False))
        return 0
    if args.cmd == "rules":
        print(json.dumps(rb.rules_at(args.scheme, args.date), ensure_ascii=False, indent=2))
        return 0
    if args.cmd == "snapshot":
        text = json.dumps(snapshot(rb), ensure_ascii=False, indent=2)
        if args.out:
            Path(args.out).write_text(text, encoding="utf-8")
        else:
            print(text)
        return 0
    return 2


if __name__ == "__main__":
    sys.exit(main())

"""A tiny, whitelisted expression evaluator for rule conditions.

Rule files are edited by an AI agent, so they must never be able to run
arbitrary Python. Only comparisons, boolean logic, arithmetic, attribute
access on `person` and `params`, literals and a few pure functions are allowed.
"""

from __future__ import annotations

import ast
import operator
from typing import Any

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}
_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}
_FUNCS = {"min": min, "max": max, "abs": abs, "len": len}
_ROOTS = {"person", "params"}


class RuleExpressionError(ValueError):
    pass


class Namespace:
    """Attribute access over a dict, with a clear error for unknown names."""

    def __init__(self, label: str, values: dict[str, Any]):
        self._label = label
        self._values = values

    def get(self, name: str) -> Any:
        if name not in self._values:
            raise RuleExpressionError(f"unknown {self._label} field '{name}'")
        return self._values[name]


def names_used(expr: str) -> set[tuple[str, str]]:
    """Return {(root, attribute)} pairs referenced by an expression."""
    tree = _parse(expr)
    used = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name):
            used.add((node.value.id, node.attr))
    return used


def _parse(expr: str) -> ast.Expression:
    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError as e:
        raise RuleExpressionError(f"invalid expression {expr!r}: {e.msg}") from e
    for node in ast.walk(tree):
        allowed = (
            ast.Expression, ast.BoolOp, ast.And, ast.Or, ast.UnaryOp, ast.Not, ast.USub,
            ast.BinOp, ast.Compare, ast.Name, ast.Attribute, ast.Constant, ast.List,
            ast.Tuple, ast.Load, ast.Call, ast.IfExp,
            *_BIN_OPS.keys(), *_CMP_OPS.keys(),
        )
        if not isinstance(node, allowed):
            raise RuleExpressionError(f"'{type(node).__name__}' is not allowed in rule expressions")
        if isinstance(node, ast.Name) and node.id not in _ROOTS | set(_FUNCS) | {"True", "False", "None"}:
            raise RuleExpressionError(f"unknown name '{node.id}'")
        if isinstance(node, ast.Call):
            if not (isinstance(node.func, ast.Name) and node.func.id in _FUNCS) or node.keywords:
                raise RuleExpressionError("only min, max, abs and len may be called")
        if isinstance(node, ast.Attribute) and not (isinstance(node.value, ast.Name) and node.value.id in _ROOTS):
            raise RuleExpressionError("attributes are only allowed on person and params")
    return tree


def evaluate(expr: str, person: dict[str, Any], params: dict[str, Any]) -> Any:
    tree = _parse(expr)
    env = {"person": Namespace("person", person), "params": Namespace("parameter", params)}
    return _eval(tree.body, env)


def _eval(node: ast.AST, env: dict[str, Namespace]) -> Any:
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, (ast.List, ast.Tuple)):
        return [_eval(e, env) for e in node.elts]
    if isinstance(node, ast.Attribute):
        return env[node.value.id].get(node.attr)  # type: ignore[union-attr]
    if isinstance(node, ast.Name):
        return {"True": True, "False": False, "None": None}[node.id]
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            return all(_eval(v, env) for v in node.values)
        return any(_eval(v, env) for v in node.values)
    if isinstance(node, ast.UnaryOp):
        val = _eval(node.operand, env)
        return (not val) if isinstance(node.op, ast.Not) else -val
    if isinstance(node, ast.BinOp):
        return _BIN_OPS[type(node.op)](_eval(node.left, env), _eval(node.right, env))
    if isinstance(node, ast.Compare):
        left = _eval(node.left, env)
        for op, comp in zip(node.ops, node.comparators):
            right = _eval(comp, env)
            if not _CMP_OPS[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.IfExp):
        return _eval(node.body, env) if _eval(node.test, env) else _eval(node.orelse, env)
    if isinstance(node, ast.Call):
        return _FUNCS[node.func.id](*[_eval(a, env) for a in node.args])  # type: ignore[union-attr]
    raise RuleExpressionError(f"cannot evaluate {type(node).__name__}")

